SET NAMES utf8mb4;

-- Container MySQL chay gio UTC con ung dung doc/ghi theo Asia/Ho_Chi_Minh
-- (xem serverTimezone trong application.yml). Neu seed dung thang NOW() thi moi moc
-- thoi gian bi lui 7 tieng, khien EnergyService tuong da troi qua 7 gio va hoi day
-- nang luong ngay lan goi API dau tien. Vi vay dung @vn_now = gio Viet Nam.
SET @vn_now := CONVERT_TZ(NOW(), '+00:00', '+07:00');
SET @vn_today := DATE(@vn_now);

-- Xoa cac tai khoan demo cu (id >= 100) va toan bo trang thai hoc cua chung
DELETE FROM users WHERE id >= 100;

-- Cac tai khoan test cu (Test Hang Dong/Bac/Vang) doi thanh hoc vien co ten that
DELETE FROM user_lesson_progress WHERE user_id IN (2,3,4);
DELETE FROM user_mistakes WHERE user_id IN (2,3,4);
DELETE FROM lesson_attempt_answers WHERE user_id IN (2,3,4);
DELETE FROM users WHERE id IN (2,3,4);

